1	import { SupabaseClient } from "@supabase/supabase-js";
2	
3	/**
4	 * Attendance -> contest auto-enrollment (issue #137).
5	 *
6	 * The sibling to `option-contest-sync.ts`: where that helper wires an
7	 * explicit option opt-in to a contest, this one wires plain trip
8	 * attendance to the "everybody plays" contests — Calcutta, the per-day
9	 * Scramble, and the KGB Cup. Any contest with
10	 * `contests.auto_enroll_attendees = true` gets every on-roster Loozer
11	 * mirrored into `contest_participants`.
12	 *
13	 * Enroll direction is purely additive and idempotent. Removal is guarded:
14	 * we refuse to delete a participant whose row (or related team/pair) carries
15	 * scoring or bidding state a human needs to unwind by hand.
16	 */
17	
18	export interface AttendanceSyncWarning {
19	  contestId: string;
20	  contestName: string;
21	  reason: string;
22	}
23	
24	export interface AttendanceSyncResult {
25	  enrolled: string[]; // contest ids the user was added to
26	  removed: string[]; // contest ids the user was removed from
27	  skipped: string[]; // contest ids skipped (already enrolled / excluded)
28	  warnings: AttendanceSyncWarning[]; // removals refused to protect state
29	}
30	
31	/**
32	 * Return the set of auto-enroll contests for a trip that carry protected
33	 * state for `userId` — i.e. removing the participant would orphan a
34	 * Calcutta bid/ownership, a scramble team seat, or a KGB Cup pairing.
35	 * Keyed by contest id -> human reason.
36	 */
37	async function protectedContests(
38	  adminClient: SupabaseClient,
39	  contests: Array<{ id: string; name: string; contest_type: string }>,
40	  userId: string,
41	): Promise<Map<string, string>> {
42	  const guarded = new Map<string, string>();
43	  const contestIds = contests.map((c) => c.id);
44	  if (contestIds.length === 0) return guarded;
45	
46	  // Calcutta: a participant row with a bid or an owner is live auction state.
47	  const { data: bids } = await adminClient
48	    .from("contest_participants")
49	    .select("contest_id, bid_amount, owner_id")
50	    .eq("user_id", userId)
51	    .in("contest_id", contestIds);
52	  for (const row of bids || []) {
53	    if (row.bid_amount != null || row.owner_id != null) {
54	      guarded.set(row.contest_id, "has a Calcutta bid or owns an auction lot");
55	    }
56	  }
57	  // Calcutta ownership can also be a buyback share pointing at *another*
58	  // participant row in these contests.
59	  const { data: parts } = await adminClient
60	    .from("contest_participants")
61	    .select("id, contest_id")
62	    .in("contest_id", contestIds);
63	  const partIdToContest = new Map((parts || []).map((p) => [p.id, p.contest_id]));
64	  if (partIdToContest.size > 0) {
65	    const { data: owns } = await adminClient
66	      .from("calcutta_ownership")
67	      .select("participant_id")
68	      .eq("owner_id", userId)
69	      .in("participant_id", Array.from(partIdToContest.keys()));
70	    for (const o of owns || []) {
71	      const cid = partIdToContest.get(o.participant_id);
72	      if (cid) guarded.set(cid, "owns a Calcutta share");
73	    }
74	  }
75	
76	  // Scramble: seated on a team in one of these contests.
77	  const { data: scrambleTeams } = await adminClient
78	    .from("scramble_teams")
79	    .select("id, contest_id")
80	    .in("contest_id", contestIds);
81	  const scrambleTeamToContest = new Map((scrambleTeams || []).map((t) => [t.id, t.contest_id]));
82	  if (scrambleTeamToContest.size > 0) {
83	    const { data: members } = await adminClient
84	      .from("scramble_team_members")
85	      .select("team_id")
86	      .eq("user_id", userId)
87	      .in("team_id", Array.from(scrambleTeamToContest.keys()));
88	    for (const m of members || []) {
89	      const cid = scrambleTeamToContest.get(m.team_id);
90	      if (cid) guarded.set(cid, "is on a scramble team");
91	    }
92	  }
93	
94	  // KGB Cup: named in a ryder cup pairing.
95	  const { data: ryderTeams } = await adminClient
96	    .from("ryder_cup_teams")
97	    .select("id, contest_id")
98	    .in("contest_id", contestIds);
99	  const ryderTeamToContest = new Map((ryderTeams || []).map((t) => [t.id, t.contest_id]));
100	  if (ryderTeamToContest.size > 0) {
101	    const teamIds = Array.from(ryderTeamToContest.keys());
102	    const { data: pairs } = await adminClient
103	      .from("ryder_cup_pairs")
104	      .select("team_id, player_a_id, player_b_id, player_c_id")
105	      .in("team_id", teamIds)
106	      .or(`player_a_id.eq.${userId},player_b_id.eq.${userId},player_c_id.eq.${userId}`);
107	    for (const p of pairs || []) {
108	      const cid = ryderTeamToContest.get(p.team_id);
109	      if (cid) guarded.set(cid, "is in a KGB Cup pairing");
110	    }
111	  }
112	
113	  return guarded;
114	}
