116	/**
117	 * Mirror a Loozer's trip attendance into every `auto_enroll_attendees`
118	 * contest on the trip.
119	 *
120	 * @param onRoster - the *new* value of event_participants.on_roster.
121	 *   true  -> upsert into every auto-enroll contest (unless a manual-removal
122	 *            tombstone exists in contest_enrollment_exclusions).
123	 *   false -> remove from every auto-enroll contest, refusing (and warning)
124	 *            where protected state exists.
125	 *
126	 * Never touches `pickem_payments` — auto-enroll contests are never Pickem,
127	 * and we must not fabricate an entry-fee-paid row (edge case in #137).
128	 * Idempotent; safe to run alongside `syncContestEnrollment`.
129	 */
130	export async function syncAttendanceEnrollment(
131	  adminClient: SupabaseClient,
132	  tripId: string,
133	  userId: string,
134	  onRoster: boolean,
135	): Promise<AttendanceSyncResult> {
136	  const result: AttendanceSyncResult = { enrolled: [], removed: [], skipped: [], warnings: [] };
137	
138	  const { data: contests } = await adminClient
139	    .from("contests")
140	    .select("id, name, contest_type")
141	    .eq("trip_id", tripId)
142	    .eq("auto_enroll_attendees", true);
143	  if (!contests || contests.length === 0) return result;
144	
145	  if (onRoster) {
146	    // Respect manual de-enroll tombstones: never auto-re-add someone who
147	    // explicitly opted out of a contest while staying on the trip.
148	    const { data: exclusions } = await adminClient
149	      .from("contest_enrollment_exclusions")
150	      .select("contest_id")
151	      .eq("user_id", userId)
152	      .in("contest_id", contests.map((c) => c.id));
153	    const excluded = new Set((exclusions || []).map((e) => e.contest_id));
154	
155	    const toAdd = contests.filter((c) => !excluded.has(c.id));
156	    if (toAdd.length > 0) {
157	      const { error } = await adminClient
158	        .from("contest_participants")
159	        .upsert(
160	          toAdd.map((c) => ({ contest_id: c.id, user_id: userId })),
161	          { onConflict: "contest_id,user_id", ignoreDuplicates: true },
162	        );
163	      if (error) throw error;
164	    }
165	    result.enrolled = toAdd.map((c) => c.id);
166	    result.skipped = contests.filter((c) => excluded.has(c.id)).map((c) => c.id);
167	    return result;
168	  }
169	
170	  // Leaving the roster: guarded removal.
171	  const guarded = await protectedContests(adminClient, contests, userId);
172	  const removable = contests.filter((c) => !guarded.has(c.id));
173	
174	  for (const c of contests) {
175	    const reason = guarded.get(c.id);
176	    if (reason) {
177	      result.warnings.push({ contestId: c.id, contestName: c.name, reason });
178	    }
179	  }
180	
181	  if (removable.length > 0) {
182	    const { error } = await adminClient
183	      .from("contest_participants")
184	      .delete()
185	      .eq("user_id", userId)
186	      .in("contest_id", removable.map((c) => c.id));
187	    if (error) throw error;
188	    result.removed = removable.map((c) => c.id);
189	  }
190	
191	  return result;
192	}
193	
194	/**
195	 * Record an explicit manual de-enrollment so future attendance syncs won't
196	 * re-add the user. Call this from the "remove me from Calcutta" gestures
197	 * (as opposed to a full roster leave). Also deletes the live participant row.
198	 */
199	export async function excludeFromContest(
200	  adminClient: SupabaseClient,
201	  contestId: string,
202	  userId: string,
203	  removedBy: string | null,
204	  reason: string | null,
205	): Promise<void> {
206	  await adminClient
207	    .from("contest_enrollment_exclusions")
208	    .upsert(
209	      { contest_id: contestId, user_id: userId, removed_by: removedBy, reason },
210	      { onConflict: "contest_id,user_id" },
211	    );
212	  await adminClient
213	    .from("contest_participants")
214	    .delete()
215	    .eq("contest_id", contestId)
216	    .eq("user_id", userId);
217	}
218	
219	/**
220	 * Clear a manual de-enrollment tombstone. Call when a Loozer opts back into
221	 * a contest they'd previously removed themselves from — the next attendance
222	 * sync (or an immediate upsert) will then re-add them.
223	 */
224	export async function clearContestExclusion(
225	  adminClient: SupabaseClient,
226	  contestId: string,
227	  userId: string,
228	): Promise<void> {
229	  await adminClient
230	    .from("contest_enrollment_exclusions")
231	    .delete()
232	    .eq("contest_id", contestId)
233	    .eq("user_id", userId);
234	}
