6	/**
7	 * @swagger
8	 * /api/admin/attendance/cell:
9	 *   put:
10	 *     summary: Toggle one (Loozer × trip) attendance cell
11	 *     description: Body — `{userId, tripId, attended}`. Writes to `event_participants` (single source for both modern and historical events after migration 00133). Checking sets `on_roster=true` and `likelihood=99`; un-checking sets `on_roster=false` and preserves the user's `likelihood` so we don't override their RSVP choice.
12	 *     tags: [Admin]
13	 *     responses:
14	 *       200: { description: Updated }
15	 *       400: { description: Bad request }
16	 *       401: { description: Unauthorized }
17	 */
18	export async function PUT(request: Request) {
19	  const admin = await checkPermissionAccess("manage_accolades");
20	  if (!admin) {
21	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
22	  }
23	
24	  const body = (await request.json()) as {
25	    userId?: string;
26	    tripId?: string;
27	    attended?: boolean;
28	  };
29	  if (!body.userId || !body.tripId || typeof body.attended !== "boolean") {
30	    return NextResponse.json(
31	      { error: "userId, tripId, and attended are required" },
32	      { status: 400 },
33	    );
34	  }
35	
36	  const adminClient = createAdminClient();
37	
38	  if (body.attended) {
39	    const { data: existing } = await adminClient
40	      .from("event_participants")
41	      .select("id")
42	      .eq("trip_id", body.tripId)
43	      .eq("user_id", body.userId)
44	      .maybeSingle();
45	    if (existing) {
46	      const { error } = await adminClient
47	        .from("event_participants")
48	        .update({ on_roster: true, likelihood: 99, likelihood_set_at: new Date().toISOString() })
49	        .eq("trip_id", body.tripId)
50	        .eq("user_id", body.userId);
51	      if (error) return NextResponse.json({ error: error.message }, { status: 500 });
52	    } else {
53	      const { error } = await adminClient.from("event_participants").insert({
54	        trip_id: body.tripId,
55	        user_id: body.userId,
56	        on_roster: true,
57	        likelihood: 99,
58	        likelihood_set_at: new Date().toISOString(),
59	      });
60	      if (error) return NextResponse.json({ error: error.message }, { status: 500 });
61	    }
62	    // Attendance -> blanket-contest enrollment (issue #137).
63	    const sync = await syncAttendanceEnrollment(adminClient, body.tripId, body.userId, true);
64	    return NextResponse.json({ success: true, enrollment: sync });
65	  } else {
66	    const { error } = await adminClient
67	      .from("event_participants")
68	      .update({ on_roster: false })
69	      .eq("trip_id", body.tripId)
70	      .eq("user_id", body.userId);
71	    if (error) return NextResponse.json({ error: error.message }, { status: 500 });
72	
73	    // Guarded un-enroll: remove from auto-enroll contests, but refuse (and
74	    // warn) where a Calcutta bid / scramble seat / KGB pairing would be
75	    // orphaned. Admin sees the warnings and unwinds those by hand.
76	    const sync = await syncAttendanceEnrollment(adminClient, body.tripId, body.userId, false);
77	    return NextResponse.json({ success: true, enrollment: sync });
78	  }
79	}
