1	import { NextResponse } from "next/server";
2	import { createClient } from "@/lib/supabase/server";
3	import { createAdminClient } from "@/lib/supabase/admin";
4	import { getEffectiveUserId, isSimulating, getEffectiveTripId } from "@/lib/simulator";
5	import { cascadeRemoveFromRoster, addToEventChat } from "@/lib/roster";
6	import { syncAttendanceEnrollment } from "@/lib/attendance-contest-sync";
7	
8	/**
9	 * @swagger
10	 * /api/rsvp:
11	 *   get:
12	 *     summary: Get current user's RSVP status for the active event
13	 *     tags: [RSVP]
14	 *     responses:
15	 *       200:
16	 *         description: RSVP status
17	 *       401:
18	 *         description: Unauthorized
19	 */
20	export async function GET() {
21	  const supabase = await createClient();
22	  const {
23	    data: { user },
24	  } = await supabase.auth.getUser();
25	
26	  if (!user) {
27	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
28	  }
29	
30	  const { data: trip } = await supabase
31	    .from("trip_settings")
32	    .select("id")
33	    .eq("id", (await getEffectiveTripId())!)
34	    .single();
35	
36	  if (!trip) {
37	    return NextResponse.json({ rsvp: null });
38	  }
39	
40	  const simulating = await isSimulating();
41	  const effectiveUserId = await getEffectiveUserId(user.id);
42	  const dbClient = simulating ? createAdminClient() : supabase;
43	
44	  const { data: rsvp } = await dbClient
45	    .from("event_participants")
46	    .select("likelihood")
47	    .eq("trip_id", trip.id)
48	    .eq("user_id", effectiveUserId)
49	    .maybeSingle();
50	
51	  return NextResponse.json({ rsvp });
52	}
53	
54	/**
55	 * @swagger
56	 * /api/rsvp:
57	 *   post:
58	 *     summary: Set RSVP likelihood for the active event
59	 *     tags: [RSVP]
60	 *     responses:
61	 *       200:
62	 *         description: RSVP updated
63	 *       401:
64	 *         description: Unauthorized
65	 */
66	export async function POST(request: Request) {
67	  const supabase = await createClient();
68	  const {
69	    data: { user },
70	  } = await supabase.auth.getUser();
71	
72	  if (!user) {
73	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
74	  }
75	
76	  try {
77	    const { likelihood } = await request.json();
78	
79	    if (![25, 50, 75, 99].includes(likelihood)) {
80	      return NextResponse.json(
81	        { error: "likelihood must be 25, 50, 75, or 99" },
82	        { status: 400 }
83	      );
84	    }
85	
86	    // Simulator support: save RSVP for the simulated user
87	    const simulating = await isSimulating();
88	    const effectiveUserId = await getEffectiveUserId(user.id);
89	    const dbClient = simulating ? createAdminClient() : supabase;
90	
91	    const { data: trip } = await supabase
92	      .from("trip_settings")
93	      .select("id")
94	      .eq("id", (await getEffectiveTripId())!)
95	      .single();
96	
97	    if (!trip) {
98	      return NextResponse.json(
99	        { error: "No active event" },
100	        { status: 400 }
101	      );
102	    }
103	
104	    const attending = likelihood === 99;
105	
106	    // Check if already has an event_participants row
107	    const { data: existing } = await dbClient
108	      .from("event_participants")
109	      .select("id, on_roster")
110	      .eq("trip_id", trip.id)
111	      .eq("user_id", effectiveUserId)
112	      .maybeSingle();
113	
114	    const wasOnRoster = existing?.on_roster ?? false;
115	
116	    // Upsert event_participants row (always keep for RSVP tracking)
117	    const adminClient = createAdminClient();
118	    const nowIso = new Date().toISOString();
119	    if (existing) {
120	      const { error } = await adminClient
121	        .from("event_participants")
122	        .update({ likelihood, on_roster: attending, likelihood_set_at: nowIso })
123	        .eq("trip_id", trip.id)
124	        .eq("user_id", effectiveUserId);
125	
126	      if (error) {
127	        return NextResponse.json({ error: error.message }, { status: 500 });
128	      }
129	    } else {
130	      const { error: insertError } = await adminClient
131	        .from("event_participants")
132	        .insert({ trip_id: trip.id, user_id: effectiveUserId, likelihood, on_roster: attending, likelihood_set_at: nowIso });
133	
134	      if (insertError) {
135	        return NextResponse.json({ error: insertError.message }, { status: 500 });
136	      }
137	    }
138	
139	    if (attending && !wasOnRoster) {
140	      // Joining the roster: add to event chat and auto-enroll into the
141	      // blanket contests everyone plays — Calcutta, Scramble, KGB Cup
142	      // (issue #137). Per-option contests still come from option
143	      // selections (issue #124); this only covers `auto_enroll_attendees`.
144	      await Promise.all([
145	        addToEventChat(trip.id, effectiveUserId),
146	        syncAttendanceEnrollment(adminClient, trip.id, effectiveUserId, true),
147	      ]);
148	    } else if (!attending && wasOnRoster) {
149	      // Explicit "I'm not coming": full hard leave — cascade remove from
150	      // every contest/team/tee-time/room/chat. (The guarded removal that
151	      // protects bidding state lives on the admin attendance toggle, where
152	      // an accidental flip shouldn't silently destroy a Calcutta bid.)
153	      await cascadeRemoveFromRoster(trip.id, effectiveUserId);
154	    }
155	
156	    return NextResponse.json({ success: true, likelihood });
157	  } catch (error) {
158	    console.error("RSVP error:", error);
159	    return NextResponse.json(
160	      { error: "Failed to update RSVP" },
161	      { status: 500 }
162	    );
163	  }
164	}
