3	import { useEffect, useMemo, useState } from "react";
4	
5	interface Trip {
6	  id: string;
7	  trip_name: string;
8	  trip_year: number;
9	  status: string;
10	}
11	
12	interface Loozer {
13	  id: string;
14	  display_name: string;
15	  avatar_url: string | null;
16	}
17	
18	interface Cell {
19	  user_id: string;
20	  trip_id: string;
21	}
22	
23	const cellKey = (userId: string, tripId: string) => `${userId}|${tripId}`;
24	
25	export function AttendanceGrid() {
26	  const [trips, setTrips] = useState<Trip[]>([]);
27	  const [loozers, setLoozers] = useState<Loozer[]>([]);
28	  const [attended, setAttended] = useState<Set<string>>(new Set());
29	  const [pending, setPending] = useState<Set<string>>(new Set());
30	  const [loading, setLoading] = useState(true);
31	  const [error, setError] = useState("");
32	  const [search, setSearch] = useState("");
33	
34	  useEffect(() => {
35	    let cancelled = false;
36	    fetch("/api/admin/attendance/grid")
37	      .then((r) => r.json().then((d) => ({ ok: r.ok, d })))
38	      .then(({ ok, d }) => {
39	        if (cancelled) return;
40	        if (!ok) {
41	          setError(d.error || "Failed to load");
42	          setLoading(false);
43	          return;
44	        }
45	        setTrips(d.trips || []);
46	        setLoozers(d.loozers || []);
47	        setAttended(
48	          new Set((d.roster || []).map((r: Cell) => cellKey(r.user_id, r.trip_id))),
49	        );
50	        setLoading(false);
51	      })
52	      .catch(() => {
53	        if (!cancelled) {
54	          setError("Failed to load");
55	          setLoading(false);
56	        }
57	      });
58	    return () => {
59	      cancelled = true;
60	    };
61	  }, []);
62	
63	  const toggle = async (userId: string, tripId: string) => {
64	    const k = cellKey(userId, tripId);
65	    if (pending.has(k)) return;
66	    const next = !attended.has(k);
67	
68	    // Optimistic update
69	    setAttended((prev) => {
70	      const n = new Set(prev);
71	      if (next) n.add(k);
72	      else n.delete(k);
73	      return n;
74	    });
75	    setPending((p) => new Set(p).add(k));
76	
77	    try {
78	      const res = await fetch("/api/admin/attendance/cell", {
79	        method: "PUT",
80	        headers: { "Content-Type": "application/json" },
81	        body: JSON.stringify({ userId, tripId, attended: next }),
82	      });
83	      if (!res.ok) {
84	        setAttended((prev) => {
85	          const n = new Set(prev);
86	          if (next) n.delete(k);
87	          else n.add(k);
88	          return n;
